/**
…
 */
function createParser(options = {}) {
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  if (typeof delimiter !== 'string' || delimiter.length !== 1 ||
      delimiter === '"' || delimiter === '\r' || delimiter === '\n') {
    throw new RangeError('delimiter must be one UTF-16 code unit other than quote, CR, or LF');
  }

  let state = 'start';
  let field = '';
  let row = [];
  let unfinished = false;
  let atStart = true;
  let previousCR = false;
  let line = 1;
  let ended = false;

  function finishField() {
    row.push(field);
    field = '';
    state = 'start';
  }

  return {
    push(chunk) {
      if (ended) throw new Error('Cannot push after end');
      if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
      const records = [];
      // Index by UTF-16 code unit, so even a surrogate delimiter works.
      for (let index = 0; index < chunk.length; index++) {
        const character = chunk[index];
        if (atStart) {
          atStart = false;
          if (character === '\uFEFF') continue;
        }

        const followsCR = previousCR;
        if (character === '\r' || (character === '\n' && !followsCR)) line++;
        previousCR = character === '\r';

        // Outside quotes a CR already emitted the row; its LF adds nothing.
        if (state !== 'quoted' && character === '\n' && followsCR) continue;
        unfinished = true;

        if (state === 'quoted') {
          if (character === '"') state = 'afterQuote';
          else field += character;
        } else if (state === 'afterQuote' && character === '"') {
          // The previous quote was the first half of an escaped quote.
          field += '"';
          state = 'quoted';
        } else if (character === delimiter) {
          finishField();
        } else if (character === '\r' || character === '\n') {
          finishField();
          records.push(row);
          row = [];
          unfinished = false;
        } else if (state === 'afterQuote') {
          throw new SyntaxError(`Unexpected character after closing quote at line ${line}`);
        } else if (state === 'start' && character === '"') {
          state = 'quoted';
        } else {
          field += character;
          state = 'unquoted';
        }
      }
      return records;
    },

    end() {
      if (ended) return [];
      ended = true;
      if (state === 'quoted') {
        throw new SyntaxError(`Unterminated quoted field at line ${line}`);
      }
      if (!unfinished) return [];
      finishField();
      const records = [row];
      row = [];
      return records;
    },
  };
}

/**
 * Parse all text using the same grammar and validation as createParser.
 * With options.header === true, convert records with the existing
 * toObjects(records, { header: true }) helper; otherwise return string[][].
 * Empty input yields [] in either mode. Do not change the helper's contract.
 */
function parse(text, options = {}) {
  const parser = createParser(options);
  const records = parser.push(text).concat(parser.end());
  return options.header === true ? toObjects(records, { header: true }) : records;
}

module.exports = { createParser, parse };

